from collections import deque
def transform(grid):
    g=[row[:] for row in grid]; h=len(g); w=max(map(len,g)); bg=max(set(x for r in g for x in r), key=lambda x:sum(r.count(x) for r in g))
    g=[row+[bg]*(w-len(row)) for row in g]
    seen=set()
    for r in range(h):
      for c in range(w):
        if g[r][c]!=bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); comp=[]; edge=False
        while q:
          y,x=q.popleft(); comp.append((y,x)); edge |= y==0 or x==0 or y==h-1 or x==w-1
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and g[yy][xx]==bg and (yy,xx) not in seen: seen.add((yy,xx)); q.append((yy,xx))
        if not edge:
          color=2 if len(comp)%2==0 else 7
          for y,x in comp:g[y][x]=color
    return g
